insert into pdf_queries (report_id, alias, seq, title, sql_text)
select report_id, 'Q1', 1, q'~Products~', to_clob(q'~select p.sku, p.name, p.category, p.price, p.tax_rate
  from pdf_demo_products p
 cross join (select level copy_no from dual connect by level <= to_number(nvl(:P30_COPIES, '1'))) c
 where p.category = nvl(:P30_CATEGORY, p.category)
   and p.sku = nvl(:P30_SKU, p.sku)
 order by p.category, p.name, c.copy_no~') from pdf_reports where code = 'PRODUCT_LABELS';
end if;
